implementation.operation:
{
  page = all(`tl.ai.htmlpages:GeneratedHtmlPage`)
    .filter(p -> $p.get(`tl.ai.htmlpages:GeneratedHtmlPage#id`) == $id)
    .firstElement();
  $page == null ? response(404) : {
    content = $page.get(`tl.ai.htmlpages:GeneratedHtmlPage#htmlContent`);
    $content == null ? response(404) : $content;
  };
}
